1	/**
2	 * @module use-mobile
3	 *
4	 * Hooks de detecção de dispositivo orientation-aware.
5	 *
6	 * Modos suportados:
7	 * - `mobile`  → viewport &lt; 768px **OU** 768-1279px em portrait
8	 *               (tablets em retrato seguem layout mobile por escolha de produto)
9	 * - `tablet`  → viewport 768-1279px **em landscape** (iPad, Surface deitado)
10	 * - `desktop` → viewport ≥ 1280px (qualquer orientação)
11	 */
12	
13	import * as React from 'react';
14	import { wideWarn } from '@/shared/lib/telemetry/wide-events';
15	
16	/** Viewport máximo (exclusivo) considerado mobile sem condicionar orientação. */
17	const MOBILE_BREAKPOINT = 768;
18	/** Viewport máximo (exclusivo) da faixa tablet; daí em diante é desktop. */
19	const TABLET_BREAKPOINT = 1280;
20	
21	export type DeviceMode = 'mobile' | 'tablet' | 'desktop';
22	
23	/**
24	 * Lê o modo atual usando `matchMedia.matches` em vez de `window.innerWidth/Height`.
25	 *
26	 * Motivo: durante `orientationchange` no iOS, `window.innerWidth/Height` pode
27	 * ainda refletir a orientação anterior por ~100ms. `matchMedia.matches` é
28	 * gerenciado pelo browser e sempre retorna o estado atual das media queries,
29	 * portanto é confiável imediatamente.
30	 */
31	function readDeviceMode(): DeviceMode {
32	  if (typeof window === 'undefined') return 'desktop';
33	  if (
34	    window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`).matches
35	  ) {
36	    return 'mobile';
37	  }
38	  if (
39	    window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`).matches
40	  ) {
41	    return 'desktop';
42	  }
43	  // 768 ≤ width < 1280: orientação decide.
44	  return window.matchMedia('(orientation: landscape)').matches
45	    ? 'tablet'
46	    : 'mobile';
47	}
